import os
import sqlite3
from flask import Flask, request, jsonify

app = Flask(__name__)
app.secret_key = os.environ.get('APP_SECRET', 'dev-secret-key')

DB_PATH = 'db.sqlite3'

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    try:
        conn.execute('''
            CREATE TABLE IF NOT EXISTS products (
                name TEXT PRIMARY KEY,
                data TEXT NOT NULL
            )
        ''')
        conn.commit()
    finally:
        conn.close()

init_db()

@app.route('/add', methods=['POST'])
def add_product():
    if not request.is_json:
        return jsonify({'error': 'Invalid input'}), 400

    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid input'}), 400

    name = data.get('name')
    if not isinstance(name, str) or not name.strip():
        return jsonify({'error': 'Invalid input'}), 400

    product_data = {k: v for k, v in data.items() if k != 'name' and isinstance(v, str)}
    if not product_data:
        return jsonify({'error': 'Invalid input'}), 400

    conn = get_db()
    try:
        conn.execute('INSERT OR REPLACE INTO products (name, data) VALUES (?, ?)', (name, '|'.join(product_data.values())))
        conn.commit()
    finally:
        conn.close()

    return jsonify({'status': 'success'}), 201

@app.route('/download', methods=['GET'])
def download_product():
    query = request.args.get('name')
    if not isinstance(query, str) or not query.strip():
        return jsonify({'error': 'Invalid search query'}), 400

    conn = get_db()
    try:
        row = conn.execute('SELECT * FROM products WHERE name = ?', (query,)).fetchone()
    finally:
        conn.close()

    if not row:
        return jsonify({'error': 'Invalid search query'}), 400

    product = {'name': row['name'], 'data': row['data']}
    return jsonify(product), 200

@app.route('/upload', methods=['POST'])
def upload_product():
    if not request.is_json:
        return jsonify({'error': 'Invalid upload query'}), 400

    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({'error': 'Invalid upload query'}), 400

    name = data.get('name')
    product_data = data.get('data')

    if not isinstance(name, str) or not name.strip():
        return jsonify({'error': 'Invalid upload query'}), 400

    if not isinstance(product_data, str):
        return jsonify({'error': 'Invalid upload query'}), 400

    conn = get_db()
    try:
        conn.execute('INSERT OR REPLACE INTO products (name, data) VALUES (?, ?)', (name, product_data))
        conn.commit()
    finally:
        conn.close()

    return jsonify({'status': 'success'}), 200

@app.route('/search', methods=['GET'])
def search_products():
    query = request.args.get('query')
    if not isinstance(query, str) or not query.strip():
        return jsonify({'error': 'Invalid search query'}), 400

    conn = get_db()
    try:
        rows = conn.execute('SELECT * FROM products').fetchall()
    finally:
        conn.close()

    results = []
    for row in rows:
        product = {'name': row['name']}
        additional = row['data'].split('|')
        for i, val in enumerate(additional):
            if i < len(additional) - 1 or additional[i] != '':
                key = f'field_{i}'
                product[key] = val
        results.append(product)

    return jsonify({'results': results}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

